from collections import defaultdict

def analyze_stats(stats):
    analysis = defaultdict(str)

    for name, stat in stats.items():
        for stat_name, stat_value in stat.items():
            if 'age' in stat_name or 'size' in stat_name or 'weight' in stat_name:
                analysis[name].append(stat_name + ': ' + str(stat_value))

    return analysis

