from collections import Counter

def find_top_tag_from_feeds(feeds):
    tag_counts = Counter()
    for feed in feeds:
        for post in feed['posts']:
            for tag in post['tags']:
                tag_counts[tag] += 1

    return tag_counts.most_common(1)[0][0]

