import os
import hashlib
from pathlib import Path

def hash_file(path):
    m = hashlib.sha256()
    with open(path, 'rb') as f:
        while True:
            data = f.read(8192)
            if not data:
                break
            m.update(data)
    return m.digest()

def delete_file(path):
    os.remove(path)
    return hash_file(path)
delete_file("secret.txt")

